--
-- Create model Course
--
CREATE TABLE "app_course" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "course_code" varchar(20) NOT NULL UNIQUE, "course_name" varchar(200) NOT NULL);
--
-- Create model User
--
CREATE TABLE "app_user" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "password" varchar(128) NOT NULL, "last_login" timestamp with time zone NULL, "is_superuser" boolean NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "is_staff" boolean NOT NULL, "is_active" boolean NOT NULL, "date_joined" timestamp with time zone NOT NULL, "email" varchar(254) NOT NULL UNIQUE, "role" varchar(20) NOT NULL);
CREATE TABLE "app_user_groups" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NOT NULL, "group_id" integer NOT NULL);
CREATE TABLE "app_user_user_permissions" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NOT NULL, "permission_id" integer NOT NULL);
--
-- Create model CourseContext
--
CREATE TABLE "app_coursecontext" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "text_chunk" text NOT NULL, "page_number" integer NOT NULL, "block_number" integer NOT NULL, "unit_number" integer NOT NULL, "embedding" vector(384) NOT NULL, "course_id" bigint NOT NULL);
--
-- Create model EvaluationBatch
--
CREATE TABLE "app_evaluationbatch" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "batch_name" varchar(100) NOT NULL, "upload_date" timestamp with time zone NOT NULL, "status" varchar(20) NOT NULL, "admin_id" bigint NOT NULL);
--
-- Create model AssignmentSubmission
--
CREATE TABLE "app_assignmentsubmission" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "enrollment_number" varchar(20) NOT NULL, "extracted_text" text NOT NULL, "file_path" varchar(255) NOT NULL, "status" varchar(20) NOT NULL, "evaluator_id" bigint NULL, "course_id" bigint NOT NULL, "batch_id" bigint NOT NULL);
--
-- Create model EvaluationResult
--
CREATE TABLE "app_evaluationresult" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "score_content" numeric(5, 2) NOT NULL, "score_linguistic" numeric(5, 2) NOT NULL, "score_presentation" numeric(5, 2) NOT NULL, "suggested_final_score" numeric(5, 2) NOT NULL, "human_final_score" numeric(5, 2) NULL, "plagiarism_percentage" integer NOT NULL, "ai_percentage" integer NOT NULL, "evaluator_remarks" text NULL, "audit_logic" jsonb NOT NULL, "reviewed_at" timestamp with time zone NULL, "submission_id" bigint NOT NULL UNIQUE);
--
-- Create model EvaluatorExpertise
--
